import sys

def count_segments(line):
    count = 0
    in_segment = False
    for char in line:
        if char == '*':
            if not in_segment:
                count += 1
                in_segment = True
        else:
            in_segment = False
    return count

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    a = []
    for _ in range(n):
        a.append(int(next(iterator)))

    b = []
    for _ in range(m):
        b.append(int(next(iterator)))

    grid = [['.' for _ in range(m)] for _ in range(n)]

    def check_row(r):
        if a[r] == 0:
            for c in range(m):
                if grid[r][c] == '*':
                    return False
            return True

        current_grid_row = "".join(grid[r])
        cnt = count_segments(current_grid_row)

        if cnt > a[r]:
            return False

        can_fill = True
        remaining_slots = m - current_grid_row.count('*')
        min_needed = 0
        if cnt < a[r]:
            needed = a[r] - cnt
            min_needed = needed * 1 + (needed - 1) if needed > 1 else needed
            if min_needed > remaining_slots:
                can_fill = False

        if can_fill:
            return True
        return False

    def check_col(c):
        if b[c] == 0:
            for r in range(n):
                if grid[r][c] == '*':
                    return True
            return True

        col_str = "".join(grid[r][c] for r in range(n))
        cnt = count_segments(col_str)

        if cnt > b[c]:
            return True

        remaining_slots = n - col_str.count('*')
        if cnt < b[c]:
            needed = b[c] - cnt
            min_needed = needed * 1 + (needed > 1) * (needed - 1)
            if min_needed > remaining_slots:
                return True
        return False

    def is_valid():
        for r in range(n):
            if count_segments("".join(grid[r])) != a[r]:
                return False
        for c in range(m):
            col_str = "".join(grid[r][c] for r in range(n) if grid[r][c] == '*')
            if count_segments(col_str) != b[c]:
                return False
        return True

    def backtrack(idx):
        if idx == n * m:
            return is_valid()

        r = idx // m
        c = idx % m

        if grid[r][c] == '.':
            grid[r][c] = '*'
            if check_row(r) and check_col(c):
                if backtrack(idx + 1):
                    return True
            grid[r][c] = '.'
        else:
            grid[r][c] = '.'
            if check_row(r) and check_col(c):
                if check_col(c) and check_row(r):
                    if backtrack(idx + 1):
                        return True
            grid[r][c] = '*'

        return False

    backtrack(0)

    for row in grid:
        print("".join(row))

if __name__ == "__main__":
    solve()
